return {
  searchConfig: {
    location: {
      city: process.env.TARGET_CITY || 'Borås',
      region: 'Västra Götaland',
      country: 'Sweden',
      radius: 50,
      coordinates: {
        lat: 57.7210,
        lng: 12.9401
      }
    },
    dateRange: {
      start: new Date(),
      end: new Date(Date.now() + 90 * 24 * 60 * 60 * 1000)
    },
    eventTypes: ['business networking', 'tech meetup', 'startup event'],
    sponsorshipBudget: {
      min: 5000,
      max: 50000
    }
  },
  searchTimestamp: new Date().toISOString(),
  searchId: `research-${Date.now()}`
};

const eventbriteEvents = $('Search Eventbrite').item?.json.events || [];
const googleResults = $('Search Google').item?.json.items || [];

const allOpportunities = [
  ...eventbriteEvents.map(event => ({
    source: 'eventbrite',
    type: 'event',
    name: event.name?.text || event.name,
    description: event.description?.text || '',
    url: event.url,
    startDate: event.start?.local,
    organizer: event.organizer?.name
  })),
  ...googleResults.map(result => ({
    source: 'google',
    type: 'search_result',
    name: result.title,
    description: result.snippet,
    url: result.link
  }))
];

const seen = new Set();
const deduplicated = allOpportunities.filter(opp => {
  const key = opp.url || opp.name.toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return {
  opportunities: deduplicated,
  totalFound: deduplicated.length
};

const opportunity = $input.item.json;
const searchConfig = $('Define Search Parameters').item.json.searchConfig;

const prompt = `Evaluate this sponsorship opportunity.

**Opportunity:** ${opportunity.name}
**Description:** ${opportunity.description}
**Type:** ${opportunity.type}

**Your Business:** Automation consulting, target: SMBs, location: ${searchConfig.location.city}
**Budget:** ${searchConfig.sponsorshipBudget.min}-${searchConfig.sponsorshipBudget.max} SEK

Return JSON:
{
  "fitScore": 1-10,
  "fitReason": "Why this score",
  "audienceAlignment": "excellent|good|moderate|poor",
  "expectedROI": {
    "brandAwareness": "high|medium|low",
    "leadGeneration": "high|medium|low"
  },
  "suggestedBudget": number (SEK),
  "outreachStrategy": "How to approach",
  "priority": "high|medium|low"
}`;

return {
  prompt,
  opportunity
};

const evaluation = $input.item.json.outputJson;
const opportunity = $('Build Evaluation Prompt').item.json.opportunity;

return {
  ...opportunity,
  fitScore: evaluation.fitScore,
  fitReason: evaluation.fitReason,
  audienceAlignment: evaluation.audienceAlignment,
  expectedROI: evaluation.expectedROI,
  suggestedBudget: evaluation.suggestedBudget,
  outreachStrategy: evaluation.outreachStrategy,
  priority: evaluation.priority,
  evaluatedAt: new Date().toISOString(),
  status: 'evaluated'
};

const opportunities = $input.all();

const highPriority = opportunities.filter(o => o.json.priority === 'high' && o.json.fitScore >= 7);
const mediumPriority = opportunities.filter(o => o.json.priority === 'medium' || (o.json.fitScore >= 4 && o.json.fitScore < 7));
const lowPriority = opportunities.filter(o => o.json.priority === 'low' || o.json.fitScore < 4);

return {
  highPriority,
  mediumPriority,
  lowPriority,
  summary: {
    total: opportunities.length,
    high: highPriority.length,
    medium: mediumPriority.length,
    low: lowPriority.length,
    totalBudgetNeeded: highPriority.reduce((sum, o) => sum + (o.json.suggestedBudget || 0), 0)
  }
};

const { highPriority, summary } = $input.item.json;
const searchConfig = $('Define Search Parameters').item.json.searchConfig;

const report = `# Sponsorship Research Report
${searchConfig.location.city} - ${new Date().toLocaleDateString()}

## Summary

**Opportunities found:** ${summary.total}
- High priority: ${summary.high}
- Estimated budget: ${summary.totalBudgetNeeded.toLocaleString()} SEK

## High Priority Opportunities

${highPriority.map((opp, i) => `### ${i + 1}. ${opp.json.name}

**Fit Score:** ${opp.json.fitScore}/10
**Why:** ${opp.json.fitReason}
**Budget:** ${opp.json.suggestedBudget.toLocaleString()} SEK
**Outreach:** ${opp.json.outreachStrategy}
**Link:** ${opp.json.url}

---`).join('
')}

*Generated automatically*`;

return {
  report,
  reportTitle: `Sponsorship Research - ${searchConfig.location.city} - ${new Date().toLocaleDateString()}`,
  summary
};
